import 'package:flutter/material.dart';
import '../../models/waiting_customer.dart';
class CustomerFormDialog extends StatefulWidget{const CustomerFormDialog({this.initial,super.key});final WaitingCustomer? initial;@override State<CustomerFormDialog> createState()=>_State();}
class _State extends State<CustomerFormDialog>{final key=GlobalKey<FormState>();late DateTime date;late TextEditingController name,start,end,menu,phone,memo;late bool linked;@override void initState(){super.initState();final c=widget.initial;date=c?.preferredDate??DateTime.now().add(const Duration(days:1));name=TextEditingController(text:c?.name);start=TextEditingController(text:c?.preferredStartTime??'10:00');end=TextEditingController(text:c?.preferredEndTime??'18:00');menu=TextEditingController(text:c?.menuName);phone=TextEditingController(text:c?.phone);memo=TextEditingController(text:c?.memo);linked=c?.lineLinked??false;}@override void dispose(){for(final c in [name,start,end,menu,phone,memo])c.dispose();super.dispose();}String? req(String?v)=>v==null||v.trim().isEmpty?'入力してください':null;String? time(String?v)=>RegExp(r'^([01]\d|2[0-3]):[0-5]\d$').hasMatch(v??'')?null:'例: 09:30';
@override Widget build(BuildContext context)=>AlertDialog(title:Text(widget.initial==null?'顧客を登録':'顧客を編集'),content:SizedBox(width:500,child:Form(key:key,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'顧客名'),validator:req),ListTile(contentPadding:EdgeInsets.zero,title:const Text('希望日'),subtitle:Text('${date.year}/${date.month}/${date.day}'),onTap:()async{final d=await showDatePicker(context:context,firstDate:DateTime.now().subtract(const Duration(days:365)),lastDate:DateTime.now().add(const Duration(days:730)),initialDate:date);if(d!=null)setState(()=>date=d);}),Row(children:[Expanded(child:TextFormField(controller:start,decoration:const InputDecoration(labelText:'希望開始 (HH:mm)'),validator:time)),const SizedBox(width:8),Expanded(child:TextFormField(controller:end,decoration:const InputDecoration(labelText:'希望終了 (HH:mm)'),validator:time))]),const SizedBox(height:12),TextFormField(controller:menu,decoration:const InputDecoration(labelText:'希望メニュー'),validator:req),const SizedBox(height:12),TextFormField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'電話番号（任意）')),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('LINE連携済み'),value:linked,onChanged:(v)=>setState(()=>linked=v)),TextFormField(controller:memo,maxLines:2,decoration:const InputDecoration(labelText:'メモ（任意）'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('キャンセル')),FilledButton(onPressed:(){if(!key.currentState!.validate())return;Navigator.pop(context,WaitingCustomer(id:widget.initial?.id??'',name:name.text,preferredDate:date,preferredStartTime:start.text,preferredEndTime:end.text,menuName:menu.text,phone:phone.text,lineLinked:linked,memo:memo.text,status:widget.initial?.status??WaitingStatus.waiting,notifiedAt:widget.initial?.notifiedAt,createdAt:widget.initial?.createdAt??DateTime.now()));},child:const Text('保存'))]);}}
